import{_ as a,o as s,c as i,a2 as t}from"./chunks/framework.BM5YPQmL.js";const c=JSON.parse('{"title":"درس الفعاليات والجمعيات","description":"","frontmatter":{},"headers":[],"relativePath":"ar/guide/tutorials/events-ngo.md","filePath":"ar/guide/tutorials/events-ngo.md"}'),n={name:"ar/guide/tutorials/events-ngo.md"};function l(o,e,r,h,d,p){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="درس-الفعاليات-والجمعيات" tabindex="-1">درس الفعاليات والجمعيات <a class="header-anchor" href="#درس-الفعاليات-والجمعيات" aria-label="Permalink to &quot;درس الفعاليات والجمعيات&quot;">​</a></h1><p>في هذا الدرس تصنع فيديو موضوعه: دعوة للتطوع في يوم تنظيف الشاطئ. ستستخدم الحزمة <code>events-ngo</code> وثيمها <code>editorial</code>، ويستغرق العمل نحو عشر دقائق قبل التسجيل.</p><h2 id="_1-أنشئ-الحلقة" tabindex="-1">1. أنشئ الحلقة <a class="header-anchor" href="#_1-أنشئ-الحلقة" aria-label="Permalink to &quot;1. أنشئ الحلقة&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> volunteer-day</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --pack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> events-ngo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --template</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> volunteer-signup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lang</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ar</span></span></code></pre></div><p>استخدم <code>--lang en</code> لنسخة إنجليزية. وتضم الحزمة أيضاً القالبين <code>event-agenda</code> و<code>donation-impact</code>. يعرض <a href="./../../reference/packs.html#events-ngo">فهرس الحزم</a> كل القوالب وحقولها.</p><h2 id="_2-أدخل-بياناتك" tabindex="-1">2. أدخل بياناتك <a class="header-anchor" href="#_2-أدخل-بياناتك" aria-label="Permalink to &quot;2. أدخل بياناتك&quot;">​</a></h2><p>افتح الحلقة بالأمر <code>reelforge edit volunteer-day</code> واستبدل الأسماء والأرقام والكلمة المفتاحية الافتراضية ببياناتك، أو ابدأ من لوحة التحكم (<strong>+ New episode</strong> ثم <strong>Start from template</strong>)، فيطلب النموذج كل حقل على حدة. التزم بحدود الطول الظاهرة لكل حقل.</p><p><strong>الجمهور والنبرة.</strong> الحضور والمتطوعون والمتبرعون والشركاء. كن إنسانياً ومتفائلاً وشفافاً.</p><ul><li>أجب عن الأسئلة: ماذا؟ وأين؟ ومتى؟ وكيف يسجّل المشاهد؟ سؤالاً في كل سطر.</li><li>اعرض خطوات التسجيل على <code>phone</code> أو بمكوّن <code>steps</code>.</li><li>استخدم أرقاماً صادقة من المنظِّم؛ القصص أقوى من الإحصاءات.</li></ul><h2 id="_3-راجع-المحتوى" tabindex="-1">3. راجع المحتوى <a class="header-anchor" href="#_3-راجع-المحتوى" aria-label="Permalink to &quot;3. راجع المحتوى&quot;">​</a></h2><ul><li>أرقام الأثر والتبرعات من المنظِّم فقط، من دون تقريب للأعلى.</li><li>لا أسماء ولا وجوه لمستفيدين حقيقيين.</li><li>لا أساليب ضغط ولا وعود بإعفاءات ضريبية إلا بعد تأكيدها.</li></ul><h2 id="_4-تحقق-وسجّل-وصدّر" tabindex="-1">4. تحقق وسجّل وصدّر <a class="header-anchor" href="#_4-تحقق-وسجّل-وصدّر" aria-label="Permalink to &quot;4. تحقق وسجّل وصدّر&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> volunteer-day</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> align</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> volunteer-day</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # after you save voice.wav in the episode folder</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> render</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> volunteer-day</span></span></code></pre></div><p>يوجد مثال مكتمل في <code>packs/events-ngo/examples/open-hands-ar</code>؛ صدّره مع الخيار <code>--silent</code> للمقارنة.</p>`,14)])])}const g=a(n,[["render",l]]);export{c as __pageData,g as default};
